import java.util.Scanner;

public class Main {
    static final long MOD_CONST = 1000000007;

    static long getInputValue(Scanner sc) {
        long val = 0;
        boolean negative = false;
        char c = sc.next().charAt(0);
        while (c < '0' || c > '9') {
            if (c == '-') {
                negative = true;
            }
            c = sc.next().charAt(0);
        }
        val = c - '0';
        while (true) {
            if (!sc.hasNext()) break;
            c = sc.next().charAt(0);
            if (c < '0' || c > '9') break;
            val = val * 10 + (c - '0');
        }
        return negative ? -val : val;
    }

    static long multiplyModulo(long a, long b, long m) {
        long res = 0;
        a %= m;
        while (b > 0) {
            if ((b & 1) == 1) {
                res = (res + a) % m;
            }
            a = (a + a) % m;
            b >>= 1;
        }
        return res;
    }

    static long powerModulo(long a, long b, long m) {
        long res = 1;
        a %= m;
        while (b > 0) {
            if ((b & 1) == 1) {
                res = multiplyModulo(res, a, m);
            }
            a = multiplyModulo(a, a, m);
            b >>= 1;
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p_value = getInputValue(sc);
        long k_value = getInputValue(sc);
        long result_value;

        if (k_value == 0) {
            result_value = powerModulo(p_value, p_value - 1, MOD_CONST);
        } else if (k_value == 1) {
            result_value = powerModulo(p_value, p_value, MOD_CONST);
        } else {
            long cycle_len = 1;
            long current_val = k_value;
            while (current_val != 1) {
                current_val = (current_val * k_value) % p_value;
                cycle_len++;
            }
            result_value = powerModulo(p_value, (p_value - 1) / cycle_len, MOD_CONST);
        }
        System.out.println(result_value);
        sc.close();
    }
}
